Item.method_code:
const { item, itemNode, itemTypeName, location } = options;
const itemId = itemNode?.getAttribute('id') || item.id;
let lockedItemNode;
try {
	if (itemNode && itemTypeName === 're_Requirement') {
		lockedItemNode = aras.lockItemEx(itemNode);
	} else {
		lockedItemNode = await aras.lockItemAsync(itemId, itemTypeName);
	}
} catch (error) {
	if (error.code === 'SOAP-ENV:Server.ItemIsLockedBySomeoneElseException') {
		window.aras.removeFromCache(itemNode);
		const itemLatestVersion = window.aras.getItemById(itemTypeName, itemId, 0);
		window.aras.itemsCache.updateItem(itemLatestVersion);
		window.aras.fireEvent('ItemRefresh', {
			itemId,
			itemLatestVersion
		});
	}
	throw error;
}

const notCurrent = window.aras.getItemProperty(lockedItemNode, 'is_current') === '0';
if (notCurrent) {
	const unlockCommand = commands.commandFactory('UnlockItem', {
		...options,
		itemNode: lockedItemNode,
		item: null
	});
	await unlockCommand.execute();
	const itemLatestVersion = await window.aras.getItemLastVersion(
		itemTypeName,
		itemId
	);
	window.aras.removeFromCache(lockedItemNode);
	window.aras.itemsCache.updateItem(itemLatestVersion);
	if (location === 'ItemView') {
		window.aras.uiReShowItemEx(itemId, itemLatestVersion);
	}
	const itemLatestId = itemLatestVersion.getAttribute('id');
	window.aras.fireEvent('ItemRefresh', {
		itemId: itemLatestId,
		itemLatestVersion
	});
	const itemTypeLabel = options.itemType.label || options.itemType.name;
	const itemKeyedName = window.aras.getItemProperty(lockedItemNode, 'keyed_name');
	const message = window.aras.getResource(
		'',
		'common.unable_to_edit_old_version',
		itemTypeLabel,
		itemKeyedName
	);
	const err = new Error(message);
	err.name = 'CUIError';
	err.code = 'Client.EditOldItemVersionException';
	throw err;
}
return lockedItemNode;
